// Without factory: client hardcodes the type
NotificationService service = new EmailNotificationService(); // tight coupling!

// With Simple Factory: creation is centralized
class NotificationFactory {
    public static NotificationService create(String type) {
        switch (type) {
            case "EMAIL": return new EmailNotificationService();
            case "SMS":   return new SmsNotificationService();
            case "PUSH":  return new PushNotificationService();
            default: throw new IllegalArgumentException("Unknown: " + type);
        }
    }
}

// Client just says what it wants, not how to build it
NotificationService svc = NotificationFactory.create("EMAIL");

// ApplicationContext = the factory
@SpringBootApplication
public class App {
    public static void main(String[] args) {
        ApplicationContext ctx = SpringApplication.run(App.class, args);

        // Factory method: getBean creates/returns objects
        UserService userService = ctx.getBean(UserService.class);
        // Spring decides how to create it, handles dependencies
    }
}

// BeanFactory is the core factory interface in Spring
// ApplicationContext extends BeanFactory with more features
// AnnotationConfigApplicationContext, WebApplicationContext etc. are specializations

// Abstract Factory: creates a family of related UI components
interface UIFactory {
    Button createButton();
    TextField createTextField();
}

// Windows family: all components match
class WindowsUIFactory implements UIFactory {
    public Button createButton()    { return new WindowsButton(); }
    public TextField createTextField() { return new WindowsTextField(); }
}

// Mac family: all components match
class MacUIFactory implements UIFactory {
    public Button createButton()    { return new MacButton(); }
    public TextField createTextField() { return new MacTextField(); }
}

// Client uses UIFactory — never touches concrete classes
void buildUI(UIFactory factory) {
    Button btn = factory.createButton();
    TextField txt = factory.createTextField();
}
